def hidden_rule_fn(state):
    grid = state
    rows = len(grid)
    cols = len(grid[0])
    next_grid = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            own = grid[r][c]
            coord_class = (r + c) % 3

            # Get neighbours based on coord_class
            neighbours = []
            if coord_class == 0:
                # Diagonal tetrad (NE, NW, SE, SW)
                for dr, dc in [(-1, 1), (-1, -1), (1, 1), (1, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbours.append(grid[nr][nc])
            elif coord_class == 1:
                # Von Neumann (N, S, E, W)
                for dr, dc in [(-1, 0), (1, 0), (0, 1), (0, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbours.append(grid[nr][nc])
            elif coord_class == 2:
                # Axial-2 quad
                for dr, dc in [(-2, 0), (2, 0), (0, 2), (0, -2)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbours.append(grid[nr][nc])

            # Count f0, f1, f2
            f0 = sum(1 for v in neighbours if v == 0)
            f1 = sum(1 for v in neighbours if v == 1)
            f2 = sum(1 for v in neighbours if v == 2)

            # Rule: next = count of own value in neighbourhood
            if own == 0:
                next_grid[r][c] = f0
            elif own == 1:
                next_grid[r][c] = f1
            elif own == 2:
                next_grid[r][c] = f2

    return next_grid
